<?php require 'config.php'; if (!empty($_SESSION['uid'])) redirect(); $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); $stmt=$pdo->prepare('SELECT id,password_hash FROM users WHERE email=?'); $stmt->execute([trim($_POST['email']??'')]); $u=$stmt->fetch(); if ($u && password_verify($_POST['password']??'', $u['password_hash'])) { session_regenerate_id(true); $_SESSION['uid']=(int)$u['id']; redirect(); } $error='Email немесе құпиясөз қате.'; }
require 'header.php'; ?><section class="panel narrow"><h1>Кіру</h1><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?><form method="post"><?=csrf()?><label>Email<input type="email" name="email" required></label><label>Құпиясөз<input type="password" name="password" required></label><button>Кіру</button></form></section><?php require 'footer.php'; ?>
